pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 deposit, uint256 minSumVal) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit > 0);
        vm.assume(deposit >= minSumVal);
        vm.assume(address(this).balance >= deposit);
        try c.SetMinSum(minSumVal) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: deposit}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(balBefore) { reverted = false; }
        catch { reverted = true; }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint ethAfter = address(c).balance;
        assertTrue(!reverted
            && balAfter == 0
            && ethAfter + deposit == ethBefore);
    }

    function testFuzz_run(uint256 deposit, uint256 minSumVal) public {
        _run(deposit, minSumVal);
    }

    receive() external payable {}
}
